 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The raster repeats its separator-and-fill motif every 10 rows. For each
    # 10-row band, compress the horizontal marker line into one value per tile.
    # The tile background is the non-frame interior color.
    interior = next(v for row in grid for v in row if v not in (9,))
    # Find the regular column pitch from the vertical 9 separators.
    sep_cols = [c for c in range(w) if sum(grid[r][c] == 9 for r in range(h)) >= h - 2]
    if len(sep_cols) >= 2:
        pitch = min(b-a for a,b in zip(sep_cols, sep_cols[1:]))
    else:
        pitch = 1
    # Each output row summarizes one 10-row band, taking markers from its
    # internal horizontal line(s); repeated marks in the band agree.
    out=[]
    for start in range(0, h, 10):
        end=min(h,start+10)
        vals=[]
        for left in range(0,w,pitch):
            right=min(w,left+pitch)
            mark=next((grid[r][c] for r in range(start,end) for c in range(left,right)
                       if grid[r][c] not in (9, interior)), interior)
            vals.append(mark)
        if vals:
            out.append(vals)
    return out
