 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Lattice divider coordinates are the rows/columns largely occupied by 9.
    rows = [r for r in range(h) if sum(v == 9 for v in grid[r]) >= w - 2]
    cols = [c for c in range(w) if sum(grid[r][c] == 9 for r in range(h)) >= h - 2]
    # The repeated background is the most frequent non-divider color.
    counts = {}
    for row in grid:
        for v in row:
            if v != 9:
                counts[v] = counts.get(v, 0) + 1
    base = max(counts, key=counts.get)
    # Compressed rows are pairs of consecutive marked horizontal divider rows;
    # compressed columns are intervals between vertical divider crossings.
    marked = [r for r in rows if any(v not in (9, base) for v in grid[r])]
    out = [[base for _ in range(len(cols) - 1)] for _ in range(max(1, len(marked) - 1))]
    for i, (ra, rb) in enumerate(zip(marked, marked[1:])):
        for j, (c0, c1) in enumerate(zip(cols, cols[1:])):
            vals = [grid[r][c] for r in (ra, rb) for c in (c0, c1)
                    if grid[r][c] not in (9, base)]
            if vals and len(set(vals)) == 1:
                out[i][j] = vals[0]
    return out
